window.USLUGI_FORMAT_PRICE = function (kop) {
  if (typeof kop !== "number" || !Number.isInteger(kop)) { throw new TypeError("price must be an integer number of kopecks"); }
  if (kop < 0) { throw new RangeError("price must not be negative"); }
  var rub = Math.floor(kop / 100), k = kop % 100;
  var s = String(rub).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  if (k) { s += "," + (k < 10 ? "0" : "") + String(k); }
  return s + " ₽";
};
